+export const G = 9.81;
+
+/** Below this airspeed the wing carries nothing. The single number the whole transition turns on. */
+export const stallSpeedMs = (a: Airframe): number =>
+  Math.sqrt((2 * a.massKg * G) / (a.rhoKgM3 * a.wingAreaM2 * a.CLmax));
